// CBET Fundamentals practice deck (v26). Original exam-style items mapped to the AAMI CBET outline. Data only.
LSA.deck({
  id: "cbet", name: "CBET Fundamentals", icon: "🔌",
  section: 'Engineer Fundamentals', format: 'practice',
  notice: "These are original practice questions written to official public outlines. They are not real past exam items, not an official NCEES or AAMI practice exam, and not a license to practice. Formulas were checked against standard public references. Consult the current FE Reference Handbook and applicable standards for official work.",
  sources: {
    "openstax-up2": ["OpenStax University Physics Volume 2", "https://openstax.org/books/university-physics-volume-2/pages/1-introduction"],
    "openstax-ap": ["OpenStax Anatomy and Physiology 2e", "https://openstax.org/books/anatomy-and-physiology-2e/pages/1-introduction"],
    "hhs-hipaa": ["HHS: HIPAA for Professionals", "https://www.hhs.gov/hipaa/for-professionals/index.html"],
    "nist-csf": ["NIST Cybersecurity Framework", "https://www.nist.gov/cyberframework"],
    "healthit": ["HealthIT.gov (ONC)", "https://www.healthit.gov/"],
    "osha-elec": ["OSHA Electrical Safety", "https://www.osha.gov/electrical"],
    "cdc-precautions": ["CDC: Standard Precautions for All Patient Care", "https://www.cdc.gov/infection-control/hcp/standard-precautions/index.html"],
    "cms-cops": ["CMS Conditions of Participation", "https://www.cms.gov/medicare/health-safety-standards/conditions-participation-requirements"],
    "fda-advice": ["FDA Device Advice: Comprehensive Regulatory Assistance", "https://www.fda.gov/medical-devices/device-advice-comprehensive-regulatory-assistance"],
    "fda-safety": ["FDA Medical Device Safety", "https://www.fda.gov/medical-devices/medical-device-safety"],
    "fda-infusion": ["FDA: Infusion Pumps", "https://www.fda.gov/medical-devices/general-hospital-devices-and-supplies/infusion-pumps"],
    "fda-defib": ["FDA: External Defibrillators and AEDs", "https://www.fda.gov/medical-devices/cardiovascular-devices/external-defibrillators-aeds-and-public-access-defibrillation"],
    "fda-pulseox": ["FDA: Pulse Oximeters", "https://www.fda.gov/medical-devices/general-hospital-devices-and-supplies/pulse-oximeters"],
    "fda-vent": ["FDA: Ventilators and Accessories", "https://www.fda.gov/medical-devices/products-and-medical-procedures/ventilators"],
    "fda-ultrasound": ["FDA: Ultrasound Imaging", "https://www.fda.gov/radiation-emitting-products/medical-imaging/ultrasound-imaging"],
    "fda-digital": ["FDA Digital Health Center of Excellence", "https://www.fda.gov/medical-devices/digital-health-center-excellence"],
    "nfpa-99": ["NFPA 99, Health Care Facilities Code (cited, not pasted)", "https://www.nfpa.org/codes-and-standards/nfpa-99-standard-for-health-care-facilities"],
    "iec-60601": ["IEC 60601-1 (FDA recognized consensus standard page; cited, not pasted)", "https://www.fda.gov/medical-devices/standards-and-conformity-assessment-program/recognized-consensus-standards-recognized-consensus-standards"],
    "aami-cbet": ["AAMI: Certified Biomedical Equipment Technician (CBET) exam content outline", "https://aami.org/certifications/cbet/"],
  },
  cards: [
    { id: "cb001", ages: 'both', topic: "anatomy", s: "The primary job of the heart is to:", c: ["Filter waste from blood in the kidneys", "Pump blood through the circulatory system", "Exchange gases between air and blood", "Store bile from the liver in the gallbladder"], f: "The heart is a muscular pump that moves blood through the pulmonary and systemic circulations. Its primary job is to pump blood through the circulatory system.", keyTerm: "Pump blood through the circulatory system", src: "openstax-ap" },
    { id: "cb002", ages: 'both', topic: "anatomy", s: "Gas exchange between air and blood occurs mainly in the:", c: ["chambers of the heart", "alveoli of the lungs", "bronchi of the airways", "pulmonary arteries"], f: "Oxygen and carbon dioxide cross the alveolar-capillary membrane in the alveoli of the lungs. The left ventricle pumps oxygenated blood but does not perform that gas exchange.", keyTerm: "alveoli of the lungs", src: "openstax-ap" },
    { id: "cb003", ages: 'both', topic: "anatomy", s: "The brain is part of which system?", c: ["The digestive system", "The nervous system", "The urinary system", "The integumentary system"], f: "The brain, spinal cord, and nerves make up the nervous system, which coordinates sensation, control, and many automatic functions.", keyTerm: "The nervous system", src: "openstax-ap" },
    { id: "cb004", ages: 'both', topic: "anatomy", s: "Skin is the major organ of which system?", c: ["The respiratory system, including the lungs and airways", "The integumentary system", "The skeletal system", "The endocrine system"], f: "Skin, hair, and associated glands form the integumentary system, a barrier that also helps with sensation and temperature control.", keyTerm: "The integumentary system", src: "openstax-ap" },
    { id: "cb005", ages: 'both', topic: "anatomy", s: "In medical terms, 'hypo-' as a prefix usually means:", c: ["Above or higher than normal, as in hypertension", "Below or lower than normal, as in hypotension", "Around or surrounding a structure, as in periosteum", "Against or opposed to a structure, as in contraindication"], f: "Hypo- means below or lower than normal, as in hypotension or hypoglycemia. Hyper- means above or excessive. Peri- means around. Contra- means against.", keyTerm: "Below or lower than normal, as in hypotension", src: "openstax-ap" },
    { id: "cb006", ages: 'both', topic: "anatomy", s: "Blood returns to the right atrium of the heart mainly through the:", c: ["aorta", "vena cava", "pulmonary veins", "pulmonary trunk"], f: "Systemic venous blood enters the right atrium by the vena cava. The aorta carries blood out of the left ventricle. Pulmonary veins return blood from the lungs to the left atrium.", keyTerm: "vena cava", src: "openstax-ap" },
    { id: "cb007", ages: 'both', topic: "anatomy", s: "The musculoskeletal system includes:", c: ["Lungs, airways, and alveoli used in ventilation and gas exchange", "Bones, joints, and muscles used in support, protection, and movement", "Liver, pancreas, and intestine used in digestion and absorption of nutrients", "Eyes, ears, and receptors used in hearing and vision"], f: "Bones, joints, cartilage, and muscles work together for support, protection, and movement. Lungs belong to the respiratory system.", keyTerm: "support, protection, and movement", src: "openstax-ap" },
    { id: "cb008", ages: 'both', topic: "electricity", s: "A 12 V source drives 0.010 A through a resistor. What is the resistance? Use Ohm's law \\(V=IR\\).", c: ["0.12 ohm", "1,200 ohm", "12 ohm", "120 ohm"], f: "Ohm's law rearranged is \\(R=V/I=12/0.010=1,200\\) ohm. Using \\(V I\\) or forgetting the decimal in the current are common mistakes.", keyTerm: "1,200 ohm", src: "openstax-up2", img: "img/cbet-series.svg", imgAlt: "A simple series circuit with a voltage source and resistors." },
    { id: "cb009", ages: 'both', topic: "electricity", s: "Two resistors, \\(2.0\\,\\mathrm{k}\\Omega\\) and \\(2.0\\,\\mathrm{k}\\Omega\\), are in series with a 10 V source. What is the current?", c: ["5.0 mA", "2.5 mA", "10 mA", "2.5 amperes"], f: "Series resistance is \\(2.0+2.0=4.0\\,\\mathrm{k}\\Omega\\). Current is \\(I=V/R=10/4000=0.0025\\,\\mathrm{A}=2.5\\,\\mathrm{mA}\\).", keyTerm: "2.5 mA", src: "openstax-up2", img: "img/cbet-series.svg", imgAlt: "A series circuit with source V and resistors R1 and R2.", imgAsk: true },
    { id: "cb010", ages: 'both', topic: "electricity", s: "Two \\(100\\,\\Omega\\) resistors are in parallel on a 10 V source. What is the total current from the source?", c: ["0.10 A", "0.20 A", "0.05 A", "20 A"], f: "Each branch draws \\(10/100=0.10\\,\\mathrm{A}\\), so the source current is \\(0.20\\,\\mathrm{A}\\). Equivalently \\(R_{\\mathrm{eq}}=50\\,\\Omega\\) and \\(I=10/50=0.20\\,\\mathrm{A}\\).", keyTerm: "0.20 A", src: "openstax-up2", img: "img/cbet-parallel.svg", imgAlt: "A parallel circuit with source V and resistors R1 and R2.", imgAsk: true },
    { id: "cb011", ages: 'both', topic: "electricity", s: "A device draws 2.0 A from a 24 V DC supply. What is the power?", c: ["12 W", "48 W", "26 W", "0.083 W"], f: "Electrical power is \\(P=VI=24(2.0)=48\\) W. Also \\(P=I^{2}R\\) or \\(V^{2}/R\\) once resistance is known.", keyTerm: "48 W", src: "openstax-up2" },
    { id: "cb012", ages: 'both', topic: "electricity", s: "A line isolation monitor (LIM) in a healthcare isolated power system is used to:", c: ["Warn of a branch-circuit overload or a short on an isolated panel", "Warn of leakage or a first fault to ground on an isolated system", "Warn of a dropped phase or a low supply voltage on the isolated panel", "Warn of a patient-cable artifact or a loose lead on an isolated receptacle"], f: "In isolated power systems used in some critical care areas, a LIM watches for a first ground fault or excessive leakage and alarms so the fault can be found before a second fault occurs. That is a warning of leakage or a first fault to ground on an isolated system. It is not an overcurrent device, a phase-loss relay, or a physiologic-monitor artifact alarm.", keyTerm: "of leakage or a first fault to ground on an isolated system", src: "openstax-up2" },
    { id: "cb013", ages: 'both', topic: "electricity", s: "An uninterruptible power supply (UPS) is used mainly to:", c: ["Carry the hospital's entire electrical demand for many hours, taking over from the emergency generator", "Bridge a short utility outage until another source takes over", "Step building voltage up or down as the facility's main transformer", "Filter incoming medical air or vacuum during a utility interruption"], f: "A UPS is used to bridge a short utility outage until another source takes over, and often to provide clean power. It is not a step-up transformer, an implant charger, or a water filter.", keyTerm: "Bridge a short utility outage until another source takes over", src: "openstax-up2" },
    { id: "cb014", ages: 'both', topic: "healthit", s: "HIPAA rules for protected health information require that workforce members:", c: ["Share PHI in any in-house meeting among badge-holding personnel", "Use PHI only as needed for treatment, payment, or operations", "Use PHI for an identified teaching case in an open classroom session", "Use PHI for a product demonstration requested by a visiting vendor"], f: "The HIPAA Privacy Rule limits uses and disclosures of PHI and includes a minimum-necessary standard for many uses. Workforce members should use PHI only as needed for treatment, payment, or operations, or another permitted purpose.", keyTerm: "Use PHI only as needed for treatment, payment, or operations", src: "hhs-hipaa", also: ["nist-csf"] },
    { id: "cb015", ages: 'both', topic: "healthit", s: "A unique hardware address burned into a network interface is called a:", c: ["IPv4 network address on that interface", "MAC address, or burned-in hardware address", "default gateway address for that subnet and route", "SSID address for the wireless network"], f: "A MAC address is a unique hardware address burned into a network interface. A unique hardware address burned into a network interface is called a MAC address, or burned-in hardware address. It is not an IPv4 address, a gateway address, or an SSID.", keyTerm: "MAC address, or burned-in hardware address", src: "healthit", also: ["nist-csf"] },
    { id: "cb016", ages: 'both', topic: "healthit", s: "IPv4 address 192.168.1.20 is commonly used as:", c: ["A public, globally routable address on the open Internet, in a global registry", "A private address that is not routable on the global Internet", "A link-local APIPA address in the 169.254.0.0/16 range", "A documentation address in the 192.0.2.0/24 TEST-NET range"], f: "RFC 1918 private address space is not routable on the global WAN. Provider routers do not forward those ranges as global destinations. 192.168.1.20 is a private address in that sense, not a public address, not an APIPA 169.254 address, and not a TEST-NET documentation address.", keyTerm: "is not routable on the global", src: "healthit", also: ["nist-csf"] },
    { id: "cb017", ages: 'both', topic: "healthit", s: "The PING utility is used mainly to:", c: ["Copy a large file to gauge sustained path throughput on a wide-area link", "Test whether a host is reachable and measure round-trip time on the path", "Open a remote desktop session and change the host's IP settings", "Scan the TCP ports and list the services running on the host"], f: "PING sends ICMP echo requests and reports whether replies return, so you can test whether a host is reachable and measure round-trip time on the path. It is a basic network diagnostic, not a calibration or leakage-current tool.", keyTerm: "Test whether a host is reachable and measure round-trip time", src: "healthit", also: ["nist-csf"] },
    { id: "cb018", ages: 'both', topic: "healthit", s: "A medical device that cannot talk to the electronic medical record, even though the network is up, may have a problem with:", c: ["The display calibration on a physiologic monitor that shows waveforms", "The device interface or middleware that maps device data to the hospital EMR", "The wall receptacle and power cord on a monitor that is running", "The nurse-call cable between the bed and the hall station on a running physiologic monitor"], f: "Device-to-EMR integration often uses a gateway or middleware, commonly with a standard such as HL7. A mapping, license, or interface-engine fault can block data even when the LAN is healthy, because the device interface or middleware that maps device data to the hospital EMR is the failing step.", keyTerm: "The device interface or middleware that maps device data to the", src: "healthit", also: ["nist-csf"] },
    { id: "cb019", ages: 'both', topic: "healthit", s: "NIST cybersecurity guidance for systems that handle sensitive data emphasizes:", c: ["The CIA triad listed as the named functions", "Govern, Identify, Protect, Detect, Respond, and Recover", "A help-desk ticket workflow standing in for a cybersecurity framework", "A one-time annual audit of protect, detect, and recover work"], f: "NIST Cybersecurity Framework 2.0 organizes work into six functions, including Govern, Identify, Protect, Detect, Respond, and Recover. Patching, access control, and monitoring support that structure.", keyTerm: "Govern, Identify, Protect, Detect, Respond", src: "nist-csf" },
    { id: "cb020", ages: 'both', topic: "healthit", s: "A workstation will not boot and the display stays dark, even on a known-good monitor. A useful early hardware check is:", c: ["Reimage the PC and reload the enterprise software image", "The power supply, cabling, and POST status on the board", "Reinstall the video driver for the attached display from the enterprise image", "Reset the saved BIOS user settings"], f: "When a workstation will not boot and the display stays dark on a known-good monitor, a useful early hardware check is the power supply, cabling, and POST status on the board. Reimaging, video-driver work, or a CMOS password reset comes after basic power and POST checks.", keyTerm: "The power supply, cabling, and POST status", src: "healthit", also: ["nist-csf"] },
    { id: "cb021", ages: 'both', topic: "healthit", s: "Applying OS and application patches on networked medical systems is important because:", c: ["Delayed patching is mainly a documentation issue for surveyors", "Unpatched systems are a frequent path for malware and data breaches", "A firewall and a strong password are enough protection on a host that missed its patches for months", "A future upgrade can take the place of current patches"], f: "Timely, tested patching reduces known vulnerabilities. Unpatched systems are a frequent path for malware and data breaches. Clinical systems still need a change process so a patch does not break a device or workflow.", keyTerm: "Unpatched systems are a frequent path for malware and data breaches", src: "healthit", also: ["nist-csf"] },
    { id: "cb022", ages: 'both', topic: "healthit", s: "A wireless access point is used to:", c: ["Connect Wi-Fi clients directly to the public WAN, bypassing the facility LAN", "Connect Wi-Fi clients to the wired network, usually on the facility LAN", "Route all client traffic between subnets, doing the job of a core router", "Terminate a site-to-site VPN tunnel for remote clinics"], f: "An access point is used to connect Wi-Fi clients to the wired network, usually on the facility LAN, and sometimes to bridge other APs to the LAN. Internet access, if any, still goes through the facility network and its routers. An AP is not a replacement for a core router or the site's only VPN gateway.", keyTerm: "Connect Wi-Fi clients to the wired network", src: "healthit", also: ["nist-csf"] },
    { id: "cb023", ages: 'both', topic: "healthit", s: "A switch, as opposed to a simple hub, typically:", c: ["Floods each arrival to the attached ports, the way a hub does", "Forwards each frame to the correct port by MAC address", "Routes each packet to another subnet by IPv4 address", "Assigns each station a telephone extension in a PBX"], f: "A switch forwards each frame to the correct port by MAC address. A hub floods every frame. Inter-subnet routing is the job of a router or layer-3 device, and analog trunks belong to a PBX.", keyTerm: "Forwards each frame to the correct port by MAC address", src: "healthit", also: ["nist-csf"] },
    { id: "cb024", ages: 'both', topic: "healthit", s: "A default gateway is:", c: ["The DNS server address a host uses to resolve names", "The router address a host uses to reach other networks", "The MAC address a host uses on the local Ethernet segment", "The DHCP server address a host uses to lease an IPv4 address"], f: "If a destination is not on the local segment, the host sends packets to its default gateway, which then routes them onward. A default gateway is the router address a host uses to reach other networks.", keyTerm: "The router address a host uses to reach other networks", src: "healthit", also: ["nist-csf"] },
    { id: "cb025", ages: 'both', topic: "healthit", s: "Hardening a Windows PC used near a medical device should include:", c: ["Shared local logins left on, with updates postponed until a scheduled downtime", "Unique accounts, required sign-in, auto-lock, and timely security updates", "A single shared desktop login, left unlocked for quicker clinical access on the unit", "Third-party antivirus alone, with the screen lock and unique logins disabled"], f: "Unique credentials, sign-in, auto-lock, patching, and least privilege reduce the chance that one compromised session exposes PHI or device control. A basic hardening set is unique accounts, required sign-in, auto-lock, and timely security updates.", keyTerm: "Unique accounts, required sign-in, auto-lock, and timely security updates", src: "healthit", also: ["nist-csf"] },
    { id: "cb026", ages: 'both', topic: "healthit", s: "A virtual server is:", c: ["An OS installed directly on bare metal as the only layer", "A guest operating system running on a hypervisor above the host hardware", "A container process sharing the host kernel rather than a full guest OS", "A bootable firmware utility stored in the system ROM"], f: "A virtual server is a guest operating system running on a hypervisor above the host hardware. It is not a bare-metal install of the guest alone, a container that shares the host kernel, or a firmware utility in ROM.", keyTerm: "A guest operating system running on a hypervisor", src: "healthit", also: ["nist-csf"] },
    { id: "cb027", ages: 'both', topic: "healthit", s: "Cloud computing for a clinic means, at a basic level:", c: ["Keeping the servers in the facility's own closet, under local IT", "Using computing resources over a network, often off site, under a service model", "Moving records into a closet on site, and calling that a cloud", "Using a vendor service only inside the facility, under local IT, for one autoclave"], f: "Cloud computing means using computing resources over a network, often off site, under a service model. HIPAA still applies: a business associate agreement and security safeguards are needed when PHI is involved.", keyTerm: "Using computing resources over a network, often off site, under a service model", src: "healthit", also: ["nist-csf"] },
    { id: "cb028", ages: 'both', topic: "healthit", s: "A cable tester or toner is most useful when you need to:", c: ["Check cabling during an electrical leakage test", "Verify a copper network run and its pairs and continuity", "Calibrate a clinical analyzer using the toner as a signal source", "Sterilize a network drop before returning it to service"], f: "Testers and toners help prove a cable's identity, continuity, and sometimes pair mapping or length. They are used to identify or verify a copper network run and its pairs and continuity. They do not replace clinical analyzer instruments.", keyTerm: "Verify a copper network run and its pairs and continuity", src: "healthit", also: ["nist-csf"] },
    { id: "cb029", ages: 'both', topic: "healthit", s: "HHS has published cybersecurity performance goals for healthcare because:", c: ["Delayed hospital billing from an attack, with little effect on clinical systems", "Attacks on hospitals can disrupt care and expose PHI", "Vendors and the billing office are the main systems hit in a hospital attack", "Hospital attacks are rare enough that a written policy is sufficient"], f: "Healthcare is a frequent ransomware and breach target. Attacks on hospitals can disrupt care and expose PHI. Federal performance goals and HIPAA security requirements aim to keep systems and PHI safer so care can continue.", keyTerm: "Attacks on hospitals can disrupt care and expose PHI", src: "healthit", also: ["nist-csf"] },
    { id: "cb030", ages: 'both', topic: "healthit", s: "A KVM switch is used to:", c: ["Share one power receptacle among several medical devices", "Share a keyboard, video, and mouse among several computers", "Share one serial cable among several infusion pumps", "Share nurse-call audio with a central monitoring station on the unit"], f: "A KVM switch is used to share a keyboard, video, and mouse among several computers. It is not a power strip, a serial sharer for pumps, or a nurse-call audio bridge.", keyTerm: "Share a keyboard, video, and mouse", src: "healthit", also: ["nist-csf"] },
    { id: "cb031", ages: 'both', topic: "function", s: "Korotkoff sounds are used when measuring:", c: ["Auscultation of heart sounds alone", "Blood pressure with a cuff and stethoscope or simulator", "Breath sounds and spirometry volumes in a pulmonary lab", "Body temperature with a tympanic or skin probe"], f: "Korotkoff sounds are the noises heard while a cuff is deflated, and they are used to measure blood pressure with a cuff and stethoscope or simulator.", keyTerm: "Blood pressure with a cuff and stethoscope or simulator", src: "fda-advice" },
    { id: "cb032", ages: 'both', topic: "function", s: "Einthoven's triangle refers to:", c: ["Chest leads V1, V2, and V3 in the standard precordial set", "The three standard limb leads of the ECG, leads I, II, and III", "Augmented leads aVR, aVL, and aVF in the derived limb set", "A rhythm display of leads I, II, and III on a ward monitor"], f: "Einthoven's triangle is formed by leads I, II, and III on the right arm, left arm, and left leg. Einthoven's triangle is formed by the three standard limb leads of the ECG, leads I, II, and III. It is a basic ECG lead model, not a table or safety-sign topic.", keyTerm: "The three standard limb leads of the ECG, leads I, II, and III", src: "fda-advice", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG-style waveform showing P, QRS, and T waves." },
    { id: "cb033", ages: 'both', topic: "function", s: "On a normal ECG, the QRS complex mainly represents:", c: ["Atrial depolarization", "Ventricular depolarization", "Ventricular repolarization", "Atrial repolarization"], f: "The QRS complex mainly reflects ventricular depolarization, the large deflection that follows the small earlier wave and precedes the later recovery wave.", keyTerm: "Ventricular depolarization", src: "fda-advice", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG waveform with the P wave, QRS complex, and T wave labeled.", imgAsk: true },
    { id: "cb034", ages: 'both', topic: "function", s: "A defibrillator analyzer is used to:", c: ["Measure leakage current and ground resistance on the defibrillator", "Measure a defibrillator's output energy during a test", "Note the selected energy setting from the front panel only", "Measure battery open-circuit voltage and treat that as the energy-output result"], f: "A defibrillator analyzer is used to measure a defibrillator's output energy during a test, often with charge time and a recorded waveform, by discharging into a known test load. Leakage and ground-resistance checks belong on a safety analyzer. Reading the selected energy or a battery voltage is not a delivered-energy measurement.", keyTerm: "Measure a defibrillator's output energy during a test", src: "fda-defib" },
    { id: "cb035", ages: 'both', topic: "function", s: "An electrical safety analyzer is used to:", c: ["Measure ECG gain, SpO2 accuracy, and similar monitor points", "Measure leakage current, ground resistance, and similar safety points", "Measure infusion rate, occlusion pressure, and similar pump points", "Measure defibrillator energy, pacing current, and similar therapy points"], f: "Safety analyzers measure leakage current, ground resistance, and similar safety points against the limits in the applicable standard, for example IEC 60601 or a facility policy based on NFPA 99. Monitor, pump, and therapy output checks use other dedicated test equipment.", keyTerm: "Measure leakage current, ground resistance, and similar safety points", src: "fda-safety" },
    { id: "cb036", ages: 'both', topic: "function", s: "A physiologic simulator is used to:", c: ["Provide a known therapeutic energy pulse to a defibrillator under test", "Provide a known ECG, pressure, or SpO2 signal to a monitor", "Provide a known gas mixture to a laboratory analyzer in lieu of a cal-gas", "Charge an implanted pacemaker through the skin at the chest"], f: "A physiologic simulator is used to provide a known ECG, pressure, or SpO2 signal to a monitor so the display and alarms can be checked against a source of known value. It is not a defibrillator-energy analyzer, a cal-gas source for a lab analyzer, or a charger for an implanted pacemaker.", keyTerm: "Provide a known ECG, pressure, or SpO2 signal to a monitor", src: "fda-advice" },
    { id: "cb037", ages: 'both', topic: "function", s: "Blood pressure in the clinic is commonly reported in:", c: ["Millimeters of H2O (mmH2O)", "Millimeters of mercury (mmHg)", "Centimeters of mercury (cmHg)", "Centimeters of H2O (cmH2O)"], f: "Arterial blood pressure is measured in millimeters of mercury (mmHg). Lumens measure light, becquerel is activity, and siemens is conductance.", keyTerm: "Millimeters of mercury (mmHg)", src: "fda-advice" },
    { id: "cb038", ages: 'both', topic: "function", s: "A pulse oximeter estimates:", c: ["Venous oxygen saturation taken from a catheter blood sample in a vein", "Oxygen saturation in arterial blood from light absorbed by a pulsatile vascular bed", "End-tidal carbon dioxide taken from a sample of exhaled gas at the airway opening", "Inspired oxygen concentration taken from a gas-analysis cell in the circuit"], f: "Pulse oximetry estimates oxygen saturation in arterial blood from light absorbed by a pulsatile vascular bed, using at least two light wavelengths. EtCO2 is a capnography measurement, not the same sensor.", keyTerm: "Oxygen saturation in arterial blood from light absorbed by a", src: "fda-pulseox" },
    { id: "cb039", ages: 'both', topic: "function", s: "End-tidal CO2 (EtCO2) monitoring is used mainly to:", c: ["Follow oxygen concentration in inspired gas during anesthesia", "Follow carbon dioxide in exhaled gas during sedation or ventilation", "Follow nitrogen concentration in a medical-gas supply manifold on the wall", "Follow agent concentration in a room-air sample"], f: "End-tidal monitoring is used to follow carbon dioxide in exhaled gas during sedation or ventilation, as a breath-by-breath check of ventilation and of the airway.", keyTerm: "Follow carbon dioxide in exhaled gas during sedation or ventilation", src: "fda-advice" },
    { id: "cb040", ages: 'both', topic: "function", s: "A telemetry system in a hospital is used to:", c: ["Print a single-lead ECG at the local station on a local writer", "Send physiologic waveforms from a mobile patient to a central station", "Show live camera video on a public waiting-room screen", "Attach scanned consent forms to a patient billing claim"], f: "Hospital telemetry is used to send physiologic waveforms from a mobile patient to a central station so a staffed station can watch the tracing while the person is not tied to a ward monitor.", keyTerm: "Send physiologic waveforms from a mobile patient to a central", src: "fda-digital" },
    { id: "cb041", ages: 'both', topic: "function", s: "An infusion pump (LVP or syringe) is designed to:", c: ["Deliver fluids or medications at a set temperature only", "Deliver fluids or medications at a set rate and volume", "Deliver fluids or medications in a single unmetered bolus", "Deliver oxygen at a set flow from a wall source"], f: "Infusion devices control rate and volume. Different types (large-volume, syringe, PCA, and injectors) fit different therapies, but the basic job is to deliver fluids or medications at a set rate and volume.", keyTerm: "Deliver fluids or medications at a set rate and volume", src: "fda-infusion" },
    { id: "cb042", ages: 'both', topic: "function", s: "A PCA pump is intended to:", c: ["Let a patient request extra pain doses with the lockout interval removed", "Let a patient request extra pain doses within programmed limits", "Let a patient request extra maintenance-fluid boluses from the same pump", "Let a nurse request ventilator breaths from the PCA handset during a case"], f: "Patient-controlled analgesia pumps give a programmed basal and/or demand dose with lockout limits. A PCA pump can let a patient request extra pain doses within programmed limits.", keyTerm: "Let a patient request extra pain doses within programmed limits", src: "fda-infusion" },
    { id: "cb043", ages: 'both', topic: "function", s: "A ventilator is life-support equipment whose basic job is to:", c: ["Circulate blood on a cardiopulmonary bypass circuit in the OR", "Move air through the lungs of the patient during ventilation", "Warm the patient with a forced-air blanket in the recovery bay", "Monitor the ECG and SpO2 only during transport to another unit"], f: "Ventilators deliver a set gas pattern so they can move air through the lungs of the patient during ventilation, when breathing needs help or replacement. They require trained use, alarms, and backup power. They are not simple monitors, and they do not move blood, ECG signals, or blanket heat.", keyTerm: "Move air through the lungs of the patient during ventilation", src: "fda-vent" },
    { id: "cb044", ages: 'both', topic: "function", s: "An external defibrillator is used to:", c: ["Deliver a shock for asystole", "Deliver a shock for a dangerous heart rhythm", "Deliver a shock for pulseless electrical activity", "Deliver a shock for a documented sinus rhythm"], f: "Defibrillators treat shockable arrhythmias under clinical protocols. An external defibrillator is used to deliver a shock for a dangerous heart rhythm such as ventricular fibrillation or pulseless ventricular tachycardia.", keyTerm: "Deliver a shock for a dangerous heart rhythm", src: "fda-defib" },
    { id: "cb045", ages: 'both', topic: "function", s: "An electrosurgical unit (ESU) is used in the operating room to:", c: ["Ablate or divide tissue with a high-frequency ultrasound handpiece", "Cut or coagulate tissue with a high-frequency current", "Cut or ablate tissue using a surgical laser beam", "Dissect tissue using a high-pressure irrigating jet"], f: "ESUs deliver a high-frequency current through an active electrode, with a return path (monopolar) or between the tips (bipolar), to cut or coagulate tissue. Safe use depends on return-electrode integrity, accessories, and smoke control. An ESU is used to cut or coagulate tissue with a high-frequency current.", keyTerm: "high-frequency current", src: "fda-advice" },
    { id: "cb046", ages: 'both', topic: "safety", s: "Patient leakage current, as used in electrical safety testing of medical equipment, is:", c: ["Current found in the protective earth conductor during a protective-earth current test", "Current measured in an applied part connected to the patient circuit", "Current taken at the mains plug during a dielectric strength test", "Current obtained at a network port during a data-cable certification test"], f: "Patient leakage current is current measured in an applied part connected to the patient circuit. Protective-earth current, dielectric-strength tests, and data-cable checks are different measurements.", keyTerm: "Current measured in an applied part", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb047", ages: 'both', topic: "function", s: "An autoclave uses which combination as its basic killing method?", c: ["Dry heat at a documented time and temperature, at atmospheric pressure", "Saturated steam under pressure at a documented time and temperature", "A chemical wipe of the chamber at ambient conditions", "Ethylene oxide gas at a documented cycle, at atmospheric pressure"], f: "Steam sterilizers (autoclaves) use saturated steam under pressure at a documented time and temperature, often with a recorded load process. Dry heat and ethylene oxide are other sterilization methods, not the basic autoclave cycle, and a chamber wipe is not a validated sterilizing process.", keyTerm: "Saturated steam under pressure at a documented time and temperature", src: "fda-advice" },
    { id: "cb048", ages: 'both', topic: "function", s: "A laboratory centrifuge is used to:", c: ["Incubate a sample at a set temperature in a heating block", "Separate components of a sample by spinning the tube at speed", "Mix a sample by gentle agitation on a laboratory rocker for several minutes at a fixed temperature", "Cool a sample in a circulating bath to a stated temperature"], f: "Centrifuges spin samples so denser components move outward. They separate components of a sample by spinning the tube at speed. Imbalance, lid interlocks, and speed verification are typical safety and performance points.", keyTerm: "Separate components of a sample by spinning the tube at speed", src: "fda-advice" },
    { id: "cb049", ages: 'both', topic: "function", s: "A laboratory refrigerator or freezer is important because:", c: ["It keeps reagents and samples at ambient temperature for easier access during working hours", "It keeps reagents and samples at the required storage temperature and alarm limits", "It sterilizes surgical instruments by freezing them to a documented temperature", "It charges device batteries overnight in a cold cabinet reserved for that work"], f: "Lab cold storage is important because it keeps reagents and samples at the required storage temperature and alarm limits, often with monitoring. Freezing is not a sterilizer for surgical tools, and a refrigerator is not a power system or a battery charger.", keyTerm: "It keeps reagents and samples at the required storage temperature", src: "fda-advice" },
    { id: "cb050", ages: 'both', topic: "function", s: "An ultrasound imager forms pictures mainly by:", c: ["Sending radiofrequency pulses in a strong magnetic field, as in MRI", "Sending high-frequency sound and receiving echoes", "Detecting gamma rays from an injected tracer", "Recording skin temperature with a thermal camera"], f: "Diagnostic ultrasound transmits pulses and listens for reflections, sending high-frequency sound and receiving echoes. MRI uses magnetic fields and radiofrequency; nuclear medicine uses radioactive tracers; thermal cameras read skin temperature.", keyTerm: "Sending high-frequency sound and receiving echoes", src: "fda-ultrasound" },
    { id: "cb051", ages: 'both', topic: "function", s: "A digital multimeter (DVM) in a shop is used to:", c: ["Read patient leakage current, treating the DVM as a safety analyzer", "Measure voltage, current, or resistance in a circuit under test", "Check defibrillator delivered energy into a 50 ohm test resistor", "Check SpO2 accuracy with a finger phantom"], f: "A DVM is general test equipment. It is used to measure voltage, current, or resistance in a circuit under test. Use it on de-energized circuits where required, with the right function and range. It is not a substitute for a medical-grade safety analyzer, a defibrillator analyzer, or an SpO2 simulator.", keyTerm: "Measure voltage, current, or resistance in a circuit under test", src: "fda-advice" },
    { id: "cb052", ages: 'both', topic: "function", s: "An SCD (sequential compression device) is used to:", c: ["Apply a sequential chest vest to assist ventilation during a respiratory treatment", "Inflate garments on a limb in a cycle to help reduce stasis in the legs", "Apply an abdominal binder to support a surgical wound during recovery from an operation", "Deliver a defibrillation shock through adhesive pads on the chest during a resuscitation"], f: "SCDs inflate garments on a limb in a cycle to help reduce stasis, applying intermittent pneumatic compression, often to the legs. They are not life-support ventilators or defibrillators.", keyTerm: "Inflate garments on a limb in a cycle to help reduce stasis", src: "fda-advice" },
    { id: "cb053", ages: 'both', topic: "function", s: "A warmer or thermal blanket system is used to:", c: ["Manage the air temperature of the entire space", "Manage body temperature for the patient", "Manage the temperature inside a supply cabinet", "Manage the humidity in a device storage closet"], f: "Temperature-management devices manage body temperature for the patient by heating or, in some systems, also cooling under a protocol. Over- or under-heating is a risk, so probes, alarms, and accessories matter.", keyTerm: "Manage body temperature for the patient", src: "fda-advice" },
    { id: "cb054", ages: 'both', topic: "function", s: "A wall suction regulator is used to:", c: ["Control oxygen flow from a wall oxygen source to a patient during therapy", "Control vacuum applied to a suction circuit from a wall source", "Control medical air pressure from a wall air source to a blender", "Generate vacuum locally with an electric pump, independent of the wall system"], f: "A wall suction regulator is used to control vacuum applied to a suction circuit from a wall source, so the applied vacuum can be set and watched. It does not meter wall oxygen or medical air, and it is not a portable suction pump that makes its own vacuum.", keyTerm: "Control vacuum applied to a suction circuit from a wall source", src: "fda-advice" },
    { id: "cb055", ages: 'both', topic: "function", s: "A fetal monitor typically tracks:", c: ["Adult ECG and NIBP on a cardiac monitor at the point of care", "Fetal heart rate and uterine activity on a labor monitor", "Overnight airflow and effort on a sleep-study system in the lab", "Telemetry waveforms on a public lobby display"], f: "Fetal monitors record FHR and contractions (TOCO on the abdomen, or intrauterine pressure when indicated) so clinicians can assess well-being in labor or testing. A fetal monitor typically tracks fetal heart rate and uterine activity on a labor monitor.", keyTerm: "Fetal heart rate and uterine activity on a labor monitor", src: "fda-advice" },
    { id: "cb056", ages: 'both', topic: "function", s: "An anesthesia machine, at a basic level, is used to:", c: ["Circulate blood on a heart-lung machine while a vaporizer is in the OR", "Deliver a mix of gases and anesthetic, and ventilate the patient", "Stand in as the only vital-signs monitor during the anesthetic", "Sterilize instruments in the OR during the anesthetic"], f: "An anesthesia machine, at a basic level, is used to deliver a mix of gases and anesthetic, and ventilate the patient, with monitoring and scavenger provisions as required. It is not a heart-lung machine, it does not replace every required monitor by itself, and it does not sterilize instruments.", keyTerm: "Deliver a mix of gases and anesthetic, and ventilate the patient", src: "fda-advice" },
    { id: "cb057", ages: 'both', topic: "function", s: "An external pacemaker (for example a transcutaneous or temporary external unit) is used to:", c: ["Deliver a defibrillation shock through pads when a shockable rhythm is present", "Deliver temporary pacing pulses through pads or a pacing lead when that strategy is indicated", "Pace only from an implanted generator present in the patient, using the external unit as a monitor", "Deliver a synchronized cardioversion through pads as the primary pacing method"], f: "An external pacemaker, whether transcutaneous or another temporary external unit, is used to deliver temporary pacing pulses through pads or a pacing lead when that strategy is indicated, under a clinical protocol. Transcutaneous pacing uses large adhesive pads, not a transvenous lead alone. Defibrillation or cardioversion is a different therapy, and an already implanted generator is not what this external unit replaces on the spot.", keyTerm: "Deliver temporary pacing pulses through pads or a pacing lead", src: "fda-advice" },
    { id: "cb058", ages: 'both', topic: "function", s: "A fluid warmer is used in perioperative or emergency care to:", c: ["Warm fluids or blood products held in a storage cabinet until they are issued", "Warm fluids or blood products for a patient during infusion or transfusion", "Warm blankets in a warming cabinet for subsequent patient use on the unit, before they are issued", "Warm contrast media in a warmer reserved for CT or angiography"], f: "Fluid warmers reduce the chance of hypothermia from cold infusions. A fluid warmer is used to warm fluids or blood products for a patient during infusion or transfusion, with the right disposables and temperature limits.", keyTerm: "Warm fluids or blood products for a patient during infusion or", src: "fda-advice" },
    { id: "cb059", ages: 'both', topic: "function", s: "A spirometer is a diagnostic device used to:", c: ["Document overnight airflow and breathing effort during a sleep study", "Measure how much air, and how fast a person moves that air in a breathing test", "Document hearing thresholds in an audiology booth with calibrated tones", "Document acuity on an eye chart in an exam area"], f: "Spirometry records volumes and flow for pulmonary testing, measuring how much air, and how fast a person moves that air in a breathing test. Calibration with a syringe and infection-control practices are typical technical points.", keyTerm: "and how fast a person moves that air in a breathing test", src: "fda-advice" },
    { id: "cb060", ages: 'both', topic: "function", s: "An otoscope is used to:", c: ["Inspect the retina of the eye with a handheld ophthalmoscope", "Look into the ear canal and at the eardrum with a lighted instrument", "Take a tympanic temperature in the ear canal with a thermometer", "Screen hearing thresholds with a handheld audiometer in the office, after otoscopy is complete"], f: "An otoscope is used to look into the ear canal and at the eardrum with a lighted instrument, so the canal and drum can be seen.", keyTerm: "Look into the ear canal and at the eardrum with a lighted instrument", src: "fda-advice" },
    { id: "cb061", ages: 'both', topic: "troubleshooting", s: "A monitor is completely dark, and no power light is on. The wall outlet is live. A sound first check is:", c: ["The LCD panel, backlight inverter, and video cable, then the display board", "The power cord, switch, and inlet fuse or breaker, then the supply", "The network drop, IP settings, and interface engine, then the EMR map", "The operating system, user profile, and display driver, then a reimage"], f: "If a monitor is fully dark and the wall outlet is live, start with the power cord, switch, and inlet fuse or breaker, then the supply. A dark unit with no power light is still a power-path problem until those parts are cleared.", keyTerm: "The power cord, switch, and inlet fuse or breaker, then the supply", src: "fda-digital" },
    { id: "cb062", ages: 'both', topic: "troubleshooting", s: "A physiologic monitor shows a flat ECG and a 'leads off' message, but a simulator on the same cable is normal. The more likely problem is:", c: ["A failed ECG amplifier or mainboard on that bedside monitor", "The electrodes, skin prep, or lead wires on the patient", "A dropped network path from the bedside monitor to the central station", "A discharged internal battery in the bedside monitor that still lets the display power on"], f: "If a known source on the same cable is normal, the monitor path can capture that signal. The more likely problem is the electrodes, skin prep, or lead wires on the patient.", keyTerm: "The electrodes, skin prep, or lead wires on the patient", src: "fda-advice", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG-style waveform used as a known test pattern." },
    { id: "cb063", ages: 'both', topic: "troubleshooting", s: "Two work orders arrive at the same time: a ventilator in use on a patient has a critical alarm, and an infusion pump in use on another patient shows a delayed battery-low notice. You should go first to the ventilator:", c: ["because its work order was entered earlier in the CMMS", "because it is in use with a critical alarm", "because the battery-low notice has been on the screen longer", "because both devices share the same default priority code"], f: "Prioritize by risk, urgency, and effect on care. You should go first to the ventilator because it is in use with a critical alarm. An in-use infusion pump with only a delayed battery-low notice is a lower immediate risk. An earlier ticket time, a longer on-screen notice, or a matching CMMS priority code does not outrank a critical alarm.", keyTerm: "because it is in use with a critical alarm", src: "fda-vent" },
    { id: "cb064", ages: 'both', topic: "troubleshooting", s: "A nurse reports 'the infusion pump is broken' after a dose was entered incorrectly and the pump alarmed in the expected way. This is best classified as:", c: ["A hardware fault, and send the pump to the shop for bench repair", "A use-related issue, and review the dose entry with the user", "An overdue calibration, and run a full performance verification", "A vendor software defect, and open a ticket for a firmware review"], f: "If a dose was entered incorrectly and the pump alarmed as designed, classify it as a use-related issue, and review the dose entry with the user. Training or a process change may still be needed, but the device did its job. A hardware repair, a full calibration, or a firmware ticket would be a different classification.", keyTerm: "A use-related issue, and review the dose entry with the user", src: "fda-infusion" },
    { id: "cb065", ages: 'both', topic: "troubleshooting", s: "One telemetry transmitter on a hall drops out, but the whole unit's other transmitters are fine. You should first suspect:", c: ["A central-station or server fault affecting the transmitters on the unit, including that wing", "A fault local to that transmitter, such as its battery, antenna, or a dead zone", "A core-network outage affecting wired and wireless systems hospital-wide", "A facility-wide telemetry antenna failure along the entire wing"], f: "When only one transmitter drops out and the rest of the unit is fine, first suspect a fault local to that transmitter, such as its battery, antenna, or a dead zone. A central-station, core-network, or facility-wide antenna fault would usually affect more than one transmitter.", keyTerm: "A fault local to that transmitter, such as its battery, antenna, or a dead zone", src: "fda-digital" },
    { id: "cb066", ages: 'both', topic: "troubleshooting", s: "Every telemetry display on a unit fails at once, while other hospital networks still work. That pattern suggests:", c: ["A single transmitter battery or lead-wire fault limited to one patient on the unit", "A shared-system problem, such as an access point, a controller, or that unit's path", "A campus-wide network collapse affecting other hospital systems and services", "A failed wall receptacle or power cord in a single patient bay on that unit, limited to that bay's devices"], f: "When every telemetry display on a unit fails at once, while other hospital networks still work, the pattern suggests a shared-system problem, such as an access point, a controller, or that unit's path. A single-patient lead or room outlet fault would not take down every display, and a campus-wide collapse would also affect other networks.", keyTerm: "that unit's path", src: "fda-digital" },
    { id: "cb067", ages: 'both', topic: "troubleshooting", s: "A newly installed monitor will not send data to the EMR, but waveforms look correct at the bedside. A useful early step is:", c: ["Recalibrate ECG and SpO2 channels on the new monitor after the move is complete", "Confirm network settings, device ID, and the interface-engine or middleware status on the new monitor", "Replace the power supply on the newly installed ward monitor", "Defer the service ticket until the upcoming scheduled preventive-maintenance visit on that unit"], f: "If a newly installed bedside monitor does not show up at the central station, confirm network settings, device ID, and the interface-engine or middleware status on the new monitor. Recalibrating physiologic channels, replacing a power supply, or deferring to the next PM does not address the missing network connection.", keyTerm: "interface-engine or middleware status", src: "fda-digital" },
    { id: "cb068", ages: 'both', topic: "troubleshooting", s: "A staff member needs a short in-service on a new vital-signs monitor. Your communication should be limited to:", c: ["The manufacturer service manual for bench repair of that vital-signs monitor", "The manufacturer instructions for use (IFU) for that monitor", "The facility standard operating procedure for device in-service", "A manufacturer training outline from a regional sales visit on that model"], f: "Technicians often give clinicians a short in-service on a new device. Limit that talk to the manufacturer instructions for use (IFU) for that monitor, which is the user-facing document for clinical operation. The service manual is written for repair work, a facility SOP is local procedure rather than the manufacturer's user IFU, and a sales-visit outline is not a substitute for the IFU.", keyTerm: "The manufacturer instructions for use (IFU) for that monitor", src: "fda-advice" },
    { id: "cb069", ages: 'both', topic: "troubleshooting", s: "A defibrillator fails an energy-output test on a defibrillator analyzer, but the device powers on. The right next path is:", c: ["Recheck that defibrillator with a second analyzer", "Remove that defibrillator from service and tag it out of clinical use", "Swap paddles or pads on that defibrillator and retest", "Report that defibrillator to the manufacturer and leave it on the cart with a sign"], f: "If output energy is outside the allowed error, remove that defibrillator from service and tag it out of clinical use. Rechecking with another analyzer, swapping paddles or pads, or reporting the problem can follow, but the unit should not stay in clinical use on the cart.", keyTerm: "Remove that defibrillator from service and tag it", src: "fda-defib" },
    { id: "cb070", ages: 'both', topic: "troubleshooting", s: "An ESU repeatedly faults with a return-electrode alarm. A practical first check is:", c: ["The generator power supply, mains cable, and chassis connections on the ESU", "The return pad, its cable, and its placement, then the generator return circuit", "The active pencil, footswitch, and cut-mode or coagulation settings on the unit", "The smoke evacuator hose and the wall suction regulator settings at the table"], f: "A repeated return-electrode alarm is often the pad, cable, or placement. A practical first check is the return pad, its cable, and its placement, then the generator return circuit.", keyTerm: "The return pad, its cable, and its placement, then the generator return circuit", src: "fda-advice" },
    { id: "cb071", ages: 'both', topic: "troubleshooting", s: "A syringe pump stops and reports occlusion. A sound first set of checks is:", c: ["Recalibrate the occlusion-pressure sensor on the syringe pump at the bench, then restart the infusion", "The tubing, clamps, and position first, then the syringe pump if the line is clear", "Install a new syringe and re-enter the prescribed infusion rate on the pump", "Send the syringe pump to biomedical engineering for a complete overhaul of the mechanism"], f: "For an occlusion alarm, check the tubing, clamps, and position first, then the syringe pump if the line is clear. Recalibration, a new syringe, or a shop overhaul comes after those bedside checks.", keyTerm: "The tubing, clamps, and position first, then the syringe pump", src: "fda-infusion" },
    { id: "cb072", ages: 'both', topic: "troubleshooting", s: "A PCA pump can be started, but the lockout interval does not match the order. After confirming the order, you should:", c: ["Re-enter the lockout from a typical unit protocol and begin the current infusion on that pump", "Treat it as a programming or configuration problem on that pump, and keep the pump unused until it is corrected", "Power-cycle the pump and begin the infusion on the current programmed settings for this patient", "Hold the pump for a future software update of the drug library and then return it to the unit"], f: "A lockout that does not match the prescribed program is a safety issue. Treat it as a programming or configuration problem and keep the pump unused until it is corrected. Do not leave it in service or change therapy limits without the proper clinical and technical process.", keyTerm: "programming or configuration problem", src: "fda-infusion" },
    { id: "cb073", ages: 'both', topic: "troubleshooting", s: "A feeding pump free-flows when the door is open and no set is loaded correctly. That is:", c: ["Remove the feeding pump from clinical use and request only a new label", "Remove the feeding pump from clinical use until a repair is completed", "Tag the feeding pump and assign it as a backup on the same unit", "Return the feeding pump after a short walk-around inspection is complete"], f: "Free-flow of enteral or IV fluid when the set is not properly engaged is a serious hazard. Free-flow is a serious safety fault, so remove the feeding pump from clinical use until a repair is completed. The device should stay out of service until that repair is done. A new label, a backup assignment on the floor, or a short visual inspection does not correct the fault.", keyTerm: "Remove the feeding pump from clinical use until a repair is completed", src: "fda-advice" },
    { id: "cb074", ages: 'both', topic: "troubleshooting", s: "A laboratory centrifuge will not start. The lid interlock still reads open even though the lid is shut. A likely cause is:", c: ["A motor or imbalance fault, so the lid is never seen as closed on that centrifuge", "A lid switch, latch, or interlock fault, so the lid is never seen as closed on that centrifuge", "A selected-speed error, with the lid recognized as closed on that centrifuge", "A worn drive belt, with the lid recognized as closed on that centrifuge"], f: "If the lid will not lock, a lid switch, latch, or interlock fault, so the lid is never seen as closed on that centrifuge, is the more likely path. A motor, speed, or belt problem usually shows up after the lid is already recognized as closed.", keyTerm: "A lid switch, latch, or interlock fault", src: "fda-advice" },
    { id: "cb075", ages: 'both', topic: "troubleshooting", s: "A lab refrigerator used for reagents is at 12 C, above its set range, and the warning did not call. You should:", c: ["Transfer the reagents to a known-good refrigerator and complete a stock inventory of what was moved", "Protect the contents, take the box out of use, and find why cooling and the alarm failed", "Adjust the temperature setpoint and leave the box in service", "Schedule a refrigeration PM for tomorrow's schedule and leave the box in service"], f: "Out-of-range storage can ruin reagents or samples. Protect the contents, take the box out of use as needed, and find why cooling and the alarm both failed. Safeguard the contents, then repair the refrigeration and the alarm path. Do not silence alarms to hide the problem.", keyTerm: "and find why cooling and the alarm", src: "fda-advice" },
    { id: "cb076", ages: 'both', topic: "troubleshooting", s: "An otoscope light is dim. The handle has fresh batteries. A simple next check is:", c: ["Replace the charging base used with that handle at the end of a full duty period", "The lamp, contacts, and head connection in that same handle", "Schedule a deferred electrical safety test of the handle", "Inspect the wall transformer output in that exam area"], f: "With fresh batteries already in the handle, a simple next check is the lamp, contacts, and head connection in that same handle, where the remaining light path still lives. The charger is not in that path once the batteries are fresh. Deferring a safety test or swapping a used speculum tip does not find a dim lamp or a poor contact.", keyTerm: "The lamp, contacts, and head connection in that same handle", src: "fda-advice" },
    { id: "cb077", ages: 'both', topic: "troubleshooting", s: "A scale used for medication dosing reads 0.4 kg high on a known test weight. You should:", c: ["Post a 0.4 kg correction factor on the scale and keep it in limited use for the rest of the day", "Remove the scale from clinical dosing use until it is calibrated or replaced and documented", "Leave the scale in dosing use and wait for the upcoming scheduled calibration cycle", "Add a journal note about the 0.4 kg error and keep the scale in dosing use on the unit"], f: "A dosing scale that fails a known test weight should be removed from clinical dosing use until it is calibrated or replaced and documented. A posted correction factor, a delay until the next cycle, or a journal note alone leaves an inaccurate scale in use.", keyTerm: "from clinical dosing use until it is calibrated or replaced and", src: "fda-advice" },
    { id: "cb078", ages: 'both', topic: "troubleshooting", s: "A stress-test ECG is noisy only when the treadmill is running. A useful direction is:", c: ["Increase the ECG waveform gain on the stress-test acquisition system during the walk", "Look for motion, cable routing, grounding, or interference from the treadmill drive on the stress-test system", "Reinstall the analysis application on the stress-test computer and repeat the study", "Replace the exam-area lighting and begin the exercise study again on the treadmill"], f: "If the ECG is noisy only when the treadmill is running, look for motion, cable routing, grounding, or interference from the treadmill drive, because the artifact tracks that source. Raising gain, defeating a safety key, or replacing software first does not find a motion or EMI path.", keyTerm: "interference from the treadmill drive", src: "fda-advice" },
    { id: "cb079", ages: 'both', topic: "troubleshooting", s: "An ultrasound unit powers on but shows no image, and a known-good probe on that connector is also dark. The fault is more likely:", c: ["A failed probe, including the known-good probe just tried on that connector", "A fault in the imaging system, rather than just the last probe you used", "A keyboard or trackball fault on the ultrasound console", "A printer or PACS connection fault on the imaging network"], f: "If a known-good probe on that connector is also dark, the fault is more likely a fault in the imaging system, rather than just the last probe you used. A keyboard, trackball, or PACS issue would not usually blank the live image from two probes.", keyTerm: "A fault in the imaging system", src: "fda-ultrasound" },
    { id: "cb080", ages: 'both', topic: "troubleshooting", s: "A pulse-oximeter reading is blank on a patient with cold fingers, but a simulator at the same cable reads 98%. This suggests:", c: ["An alarm-limit setting on the pulse oximeter", "A poor peripheral signal at the sensor site", "A probe-cable fault in the monitor path, including the adapter", "A power-supply fault inside the pulse oximeter itself"], f: "A simulator isolates the device and cable. A good simulator reading with a bad patient waveform points to a poor peripheral signal at the sensor site, rather than a proved monitor failure. Cold fingers, placement, or ambient light may be the cause, which clinicians may address. Still treat alarms seriously.", keyTerm: "A poor peripheral signal at the sensor site", src: "fda-pulseox" },
    { id: "cb081", ages: 'both', topic: "troubleshooting", s: "A ventilator in the shop fails a volume check on a test lung, outside its allowed error. You should:", c: ["Return it to the unit on completion of a walk-around inspection of the display, alarms, and power-on test, and a quick leak check", "Keep it out of service until it is repaired or escalated, then corrected and verified for a return to use", "Hold it for the upcoming scheduled PM, then issue it if the paperwork and dates are current", "Stage it as a backup ventilator after a passing power-on self-test of the unit is complete"], f: "Life-support equipment that fails a performance test stays out of service until it is corrected and verified. Keep it out of service until it is repaired or escalated, then corrected and verified for a return to use. Do not pass it by changing limits without authority.", keyTerm: "then corrected and verified for a return to use", src: "fda-vent" },
    { id: "cb082", ages: 'both', topic: "troubleshooting", s: "A balloon pump (IABP) in use has a gas-loss alarm. Your first priority is:", c: ["Stay with the clinical team at the bedside, then open a loaner request from the loaner pool for a replacement pump", "Stay with the clinical team at the bedside, then follow the emergency procedure for the device", "Stay with the clinical team at the bedside, then complete the incident paperwork", "Stay with the clinical team at the bedside, then call materials for a replacement part"], f: "A gas-loss alarm on an IABP in use is an emergency at the bedside. Your first priority is to stay with the clinical team at the bedside, then follow the emergency procedure for the device.", keyTerm: "then follow the emergency procedure for the device", src: "fda-advice" },
    { id: "cb083", ages: 'both', topic: "troubleshooting", s: "An anesthesia machine fails a pre-use leak test. The correct action is:", c: ["Leave it out of use for a case until the coming change of personnel, and keep the machine at the anesthetizing location", "Leave it out of use for a case until the leak is found and the pre-use check passes", "Leave it out of use for a case until a unit log entry is written", "Return it for the last case of the day after a walk-around check of the machine is complete"], f: "A failed pre-use leak test means the machine is not ready. Leave it out of use for a case until the leak is found and the pre-use check passes.", keyTerm: "Leave it out of use for a case until the leak is found and the pre-use", src: "fda-advice" },
    { id: "cb084", ages: 'both', topic: "troubleshooting", s: "A surgical table will not unlock to reposition, and the patient is on the table. You should:", c: ["Arrange a transfer to another table before trying the emergency unlock on this table", "Use the emergency unlock if one exists, and stop short of forcing unknown parts", "Wait for a loaner table from central supply before trying the emergency unlock in this case", "Call the equipment help desk and remain at this table for further instructions from the supervisor"], f: "With a patient on the table, an emergency release comes first. Use the emergency unlock if one exists, and stop short of forcing unknown parts. Arranging a transfer or waiting for a loaner before trying the unlock delays that release. Do not improvise with force that could injure the patient or wreck the table.", keyTerm: "Use the emergency unlock if one exists, and stop short of forcing unknown parts", src: "fda-advice" },
    { id: "cb085", ages: 'both', topic: "troubleshooting", s: "An infant warmer's skin-temperature probe is off the skin, and the unit is in servo mode. The unsafe pattern to watch for is:", c: ["Heater overshoot caused by a room-temperature probe reading in servo mode on that warmer", "Heater overshoot with the skin sensor off, and no true skin temperature", "Heater overshoot driven by a stored probe-file temperature in the warmer", "Heater overshoot from a water-bath temperature setting on the unit"], f: "In servo (skin) mode the heater is driven by the probe. A loose or detached probe can lead to overheating because the unit no longer sees a true skin temperature. The pattern to watch for is heater overshoot with the skin sensor off, and no true skin temperature. Check probe placement and mode, and follow the device's alarm behavior.", keyTerm: "Heater overshoot with the skin sensor off, and no true skin temperature", src: "fda-advice" },
    { id: "cb086", ages: 'both', topic: "troubleshooting", s: "A therapeutic ultrasound unit in physical therapy has a worn sound head and a failed completeness-of-output check. You should:", c: ["Halt treatments and post a door sign, then resume the same day on the booked patient list", "Stop treatments and leave them stopped until the applicator and output are corrected and a passing test is done", "Stop treatments and log a timer-only check as the verification of output", "Stop treatments and schedule a deferred output check, then resume the booked patients"], f: "If the sound head is worn and output cannot be verified, stop treatments and leave them stopped until the applicator and output are corrected and a passing test is done. A door sign, a timer-only check, or a later test after resuming booked patients is not enough.", keyTerm: "until the applicator and output are corrected", src: "fda-ultrasound" },
    { id: "cb087", ages: 'both', topic: "troubleshooting", s: "A video integration system in an OR has no image on the main display, but the endoscope's local screen works. A useful path is:", c: ["Recalibrate or replace the endoscope on the video tower", "Trace the video route, cables, switcher, and display", "Reboot the recording PC used for image capture in the OR", "Adjust the overhead lighting and the main-display brightness"], f: "If the endoscope's local screen works, the scope is producing a picture. A useful path is to trace the video route, cables, switcher, and display. Recalibrating the scope, rebooting only the recorder, or adjusting room lighting does not find a break in that video path.", keyTerm: "Trace the video route, cables, switcher, and display", src: "fda-advice" },
    { id: "cb088", ages: 'both', topic: "troubleshooting", s: "A circulating nurse says a newly installed device does not work the way the previous unit did. The best first technical step is:", c: ["Compare the new unit only to a wall sign about the previous model on the unit, then copy those steps", "Ask what was expected, confirm settings on the new unit, and compare to the manual and a known-good unit", "Look up a prior staff complaint ticket and match those saved settings from the file", "Copy the setup from the loaner tag and return the device to service on the unit"], f: "When a newly installed device does not behave as staff expect, ask what was expected, confirm settings on the new unit, and compare to the manual and a known-good unit. Copying a hallway sign, an old complaint ticket, or a loaner tag is a weaker first step.", keyTerm: "confirm settings on the new unit", src: "fda-advice" },
    { id: "cb089", ages: 'both', topic: "troubleshooting", s: "A module in a physiologic monitor loses only the IBP channel, while ECG and NIBP still work. That pattern suggests:", c: ["A printer or report-interface fault on the physiologic monitor, with the other channels still working", "A local fault in that pressure channel, its cable, or its transducer interface on the physiologic monitor", "A complete main-board or display failure on the physiologic monitor", "A power-supply fault affecting the full set of channels on the monitor module"], f: "If only the IBP channel is lost while ECG and NIBP still work, the pattern suggests a local fault in that pressure channel, its cable, or its transducer interface on the physiologic monitor. A printer, full main-board, or power-supply failure would usually affect more than one channel.", keyTerm: "A local fault in that pressure channel", src: "fda-advice" },
    { id: "cb090", ages: 'both', topic: "troubleshooting", s: "You finish a repair on a life-support device. Before it returns to service you should:", c: ["Power the device on, write a short bench note, and return it to service on the unit after a walk-around check is complete", "Test the functions that were affected after the repair, and complete the required documentation, then return it to service", "Update the upcoming PM date in the CMMS and return it to service", "Attach a return tag and send it to the unit for a clinical trial"], f: "After a life-support repair, test the functions that were affected after the repair, and complete the required documentation, then return it to service. A power-on note, a CMMS date change, or a clinical trial on the unit is not enough by itself.", keyTerm: "Test the functions that were affected after the repair", src: "fda-advice" },
    { id: "cb091", ages: 'both', topic: "safety", s: "A protective earth (ground) conductor on a medical device power cord is there mainly to:", c: ["Carry the normal operating current so the chassis can serve as the return conductor on that device", "Carry a low-impedance fault current so protection can operate and touch voltage stays low", "Hold the device at earth potential during normal operation only", "Isolate the chassis from earth so fault current cannot flow"], f: "The grounding conductor is a safety path for fault current, not the normal load path. A protective earth conductor is there mainly to carry a low-impedance fault current so protection can operate and touch voltage stays low. NFPA 99 and IEC 60601 address grounding and leakage in healthcare electrical systems and equipment; consult those standards for limits and methods. Using the chassis as a load return, or isolating it from earth, defeats that protection.", keyTerm: "Carry a low-impedance fault current so protection can operate and touch voltage stays low", src: "iec-60601", also: ["nfpa-99"], img: "img/cbet-plug.svg", imgAlt: "Front view of a US NEMA 5-15 receptacle with the ground hole down: the wider neutral slot is on the left, the narrower hot slot is on the right, and the ground hole is at the bottom.", imgAsk: true },
    { id: "cb092", ages: 'both', topic: "safety", s: "Macroshock and microshock are different because:", c: ["Microshock concerns only the voltage level, independent of any current path through tissue, in that model", "Microshock concerns small currents that are dangerous if they reach the heart through a conductive path", "Microshock concerns only currents that travel through intact dry skin on a limb", "Microshock concerns only currents that stay on the equipment chassis and never leave it"], f: "Macroshock is a shock through the intact body. Microshock refers to much smaller currents that can be hazardous if a conductive path (for example a catheter or lead) reaches the heart. Design and testing of patient connections take that risk into account. See IEC 60601 and NFPA 99 for the official limits and tests. Microshock concerns small currents that are dangerous if they reach the heart through a conductive path.", keyTerm: "Microshock concerns small currents that are dangerous if they reach the heart", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb093", ages: 'both', topic: "safety", s: "A GFCI device is intended to:", c: ["Open the circuit when it detects a dangerous imbalance between hot and ground current", "Open the circuit when it detects a dangerous imbalance between hot and neutral current", "Open the circuit when it detects a dangerous overvoltage between hot and neutral, like a surge protector", "Open the circuit when it detects a dangerous overload or short, like a branch circuit breaker"], f: "A GFCI is intended to open the circuit when it detects a dangerous imbalance between hot and neutral current, which can mean current is leaving the intended circuit. It does not measure current in the grounding conductor as its trip signal, and it is not a surge protector or an overcurrent breaker.", keyTerm: "Open the circuit when it detects a dangerous imbalance between hot and neutral", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb094", ages: 'both', topic: "safety", s: "A Safety Data Sheet (SDS) is used to:", c: ["List catalog numbers and reorder points for a chemical product in the storeroom", "Describe chemical hazards, PPE, storage, and emergency actions for a product", "Store a patient's medication list and known allergies in the chart", "Store the default settings of a medical device after a repair is complete, in the repair file"], f: "The SDS (formerly MSDS) describes hazards, PPE, storage, and emergency actions for a chemical product. An SDS is used to describe chemical hazards, PPE, storage, and emergency actions for a product. It is not a medical record, a purchasing catalog, or a device setting sheet.", keyTerm: "Describe chemical hazards, PPE, storage, and emergency actions for a product", src: "osha-elec", also: ["nfpa-99"] },
    { id: "cb095", ages: 'both', topic: "safety", s: "A standard ionizing-radiation trefoil warning sign is meant to:", c: ["Warn of a magnetic-field hazard in that area or on that source", "Warn of a radiation hazard in that area or on that source", "Warn of a visible-laser hazard in that area or on that source", "Warn of a biological hazard in that area or on that source"], f: "A standard ionizing-radiation trefoil sign is meant to warn of a radiation hazard in that area or on that source, so people can follow the controls posted there. The trefoil is not a magnet, laser, or biohazard symbol.", keyTerm: "Warn of a radiation hazard in that area or on that source", src: "nfpa-99" },
    { id: "cb096", ages: 'both', topic: "safety", s: "Standard precautions in a healthcare facility include:", c: ["Perform hand hygiene when the task is done, and store unused PPE for another patient", "Perform hand hygiene and wear the PPE the task requires for that patient-care work", "Perform hand hygiene at the beginning of the day only, and wear PPE if a visitor is present", "Perform hand hygiene and wear PPE only for patients on isolation precautions"], f: "Standard precautions assume that blood and body fluids may be infectious. Perform hand hygiene and wear the PPE the task requires for that patient-care work, treating body fluids as potentially infectious, with safe sharps handling and cleaning, as taught by CDC and required in facilities.", keyTerm: "Perform hand hygiene and wear the PPE the task requires for that", src: "cdc-precautions", also: ["nfpa-99"] },
    { id: "cb097", ages: 'both', topic: "function", s: "CMS (Centers for Medicare and Medicaid Services) is important to hospitals in part because:", c: ["It issues state professional-engineer licenses for hospital staff and contractors", "It sets Conditions of Participation and recognizes accrediting organizations", "It licenses medical-device manufacturers under a 510(k) program for market clearance", "It writes local fire-evacuation maps for each hospital campus, building, and ward"], f: "CMS is important to hospitals in part because it sets Conditions of Participation and recognizes accrediting organizations. Those conditions are a major reason hospitals maintain accredited safety and equipment programs.", keyTerm: "It sets Conditions of Participation and recognizes accrediting", src: "cms-cops", also: ["nfpa-99"] },
    { id: "cb098", ages: 'both', topic: "safety", s: "Under IEC 60601-1, which applied-part type has the tightest patient leakage current limits?", c: ["Type B, for general body applied parts in non-cardiac contact", "Type CF, for direct cardiac applied parts", "Type BF, for body-floating applied parts", "Type CF, for general body applied parts"], f: "Type CF applied parts, intended for direct cardiac connection, have tighter patient-leakage limits than type B or BF in IEC 60601-1, in both normal and single-fault condition. Typical teaching values are on the order of 10 microamps for CF in normal condition, versus on the order of 100 microamps for B or BF. Confirm the figures in the current edition of the standard and on the device labeling. The tightest class is Type CF, for direct cardiac applied parts.", keyTerm: "Type CF, for direct cardiac applied parts", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb099", ages: 'both', topic: "safety", s: "For a given applied-part type, IEC 60601-1 leakage current limits in single-fault condition, compared with normal condition, are:", c: ["The same numerical limit as in normal condition for that applied-part type", "Higher than in normal condition, but still limited to a stated official value", "Dropped as a requirement in single-fault condition under the standard", "Replaced by a manufacturer design target or a catalog estimate for that product"], f: "The standard allows a higher leakage current in a specified single-fault condition than in normal condition, but the current is still capped. Limits are higher than in normal condition, but still limited to a stated official value. Type CF remains tighter than type BF in both conditions. Use the values and test setup from the edition and labeling that apply.", keyTerm: "Higher than in normal condition, but still limited to a stated official value", src: "iec-60601", also: ["nfpa-99"] },
    { id: "cb100", ages: 'both', topic: "safety", s: "An MRI warning sign is posted because:", c: ["The strong magnetic field can interfere with nearby Wi-Fi and similar wireless links in the suite and adjoining passage", "The strong magnetic field pulls ferromagnetic objects and is a serious projectile hazard", "The strong magnetic field is mainly a noise-reduction benefit for staff in the suite", "The strong magnetic field is mainly a wayfinding cue for visitors in the imaging wing"], f: "MRI systems have a strong magnetic field that pulls ferromagnetic objects and is a serious projectile hazard, along with other hazards (for example, implants and time-varying fields). Access and screening rules exist to prevent projectile and implant injuries.", keyTerm: "pulls ferromagnetic objects and is a serious projectile hazard", src: "nfpa-99" },
  ]
});
